<span class="line"> <span class="token variable">$env</span>:GIT_LOG_FORMAT_DEFAULT = <span class="token string">&quot;%Cred%h%Creset %C(yellow)%d%Crest %s %Cgreen(%cr) %C(bold blue) %an %Creset&quot;</span></span>
