<span class="line"><span class="token variable">$GitPromptSettings</span><span class="token punctuation">.</span>DefaultPromptPrefix<span class="token punctuation">.</span>Text = <span class="token string">&quot;<span class="token function">$<span class="token punctuation">(</span><span class="token namespace">[char]</span>0x2192<span class="token punctuation">)</span></span> &quot;</span> <span class="token comment"># arrow unicode symbol</span></span>
